package flowkit

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"math/big"
	"strconv"
	"strings"
	"time"

	"github.com/g0-up/flowkit/internal/ids"
	"github.com/g0-up/flowkit/internal/schema"
	"github.com/g0-up/flowkit/internal/store"
)

// DraftID identifies a saved draft, a UUID generated by flowkit.
type DraftID string

// Version numbers the published versions of a definition from 1.
type Version int

// PublishOpts annotates a published version. The caller authenticates
// Actor; flowkit stores it as given.
type PublishOpts struct {
	Actor string
	Note  string
}

// DefinitionVersion is a published version of a definition.
type DefinitionVersion struct {
	Name             string
	Version          int
	Body             json.RawMessage
	MetamodelVersion int
	// Checksum is the hex SHA-256 of the body as stored, which Postgres
	// jsonb normalizes, with object keys sorted and integers spelled in
	// plain base 10. It does not depend on whitespace, key order or how an
	// integer is written; a fraction keeps the jsonb spelling, so 1.5e0
	// and 1.5 match but 1.50 does not.
	Checksum    string
	PublishedBy string
	Note        string
	PublishedAt time.Time
}

// ComponentRef names a registered component a definition uses.
type ComponentRef struct {
	// Kind is one of the constants ComponentEvent, ComponentAction and
	// ComponentFact.
	Kind string
	// Ref is the event type, action name or fact name.
	Ref string
}

// DefinitionRef names a published definition version.
type DefinitionRef struct {
	Name    string
	Version int
}

// maxDefinitionNameBytes caps the length of a definition name.
const maxDefinitionNameBytes = 255

// Definitions manages workflow definitions: drafts, published versions and
// whether a definition starts runs. Get it from Engine.Definitions.
type Definitions struct {
	e *Engine
}

// Definitions returns the definition API of the Engine.
func (e *Engine) Definitions() *Definitions { return &Definitions{e: e} }

// Validate checks body against the Engine's registry; see
// Registry.ValidateDefinition.
func (d *Definitions) Validate(body json.RawMessage) error {
	if _, verrs := d.e.reg.validateDefinition(body); len(verrs) > 0 {
		return verrs
	}
	return nil
}

// SaveDraft validates body and stores it as a draft of the named
// definition. An invalid body returns ValidationErrors and stores nothing.
func (d *Definitions) SaveDraft(ctx context.Context, name string, body json.RawMessage) (DraftID, error) {
	if err := checkDefinitionName(name); err != nil {
		return "", err
	}
	v, verrs := d.e.reg.validateDefinition(body)
	if len(verrs) > 0 {
		return "", verrs
	}
	id := ids.NewV4()
	err := d.e.inTx(ctx, func(tx store.Tx) error {
		return d.e.store.InsertDraft(ctx, tx, store.DraftRow{
			ID:               id,
			Name:             name,
			Body:             body,
			MetamodelVersion: v.def.MetamodelVersion,
			CreatedAt:        d.e.cfg.Clock.Now(),
		})
	})
	if err != nil {
		return "", fmt.Errorf("flowkit: save draft of %q: %w", name, err)
	}
	return DraftID(id.String()), nil
}

// Publish validates the draft again, against the current registry, and
// publishes it as the next version of its definition. In one transaction it
// creates the definition, enabled, if it does not exist yet; stores the
// version and the components it uses; and points the definition at the new
// version with its trigger and concurrency settings, which new events then
// route by. Runs already started keep the version they started with.
//
// Drafts do not change once saved, so publishing the same draft again
// stores another version with the same body.
//
// An unknown draft returns ErrNotFound; a draft the registry no longer
// accepts returns ValidationErrors.
func (d *Definitions) Publish(ctx context.Context, id DraftID, opts PublishOpts) (Version, error) {
	draftID, err := ids.Parse(string(id))
	if err != nil {
		return 0, fmt.Errorf("%w: draft %q", ErrNotFound, id)
	}
	for _, f := range []struct{ what, v string }{{"actor", opts.Actor}, {"note", opts.Note}} {
		if problem := textProblem(f.v); problem != "" {
			return 0, fmt.Errorf("flowkit: publish: %s %s", f.what, problem)
		}
	}
	// Validation runs outside the transaction that locks the definition,
	// so a slow one holds no lock. The draft cannot change in between.
	var draft store.DraftRow
	err = d.e.inTx(ctx, func(tx store.Tx) error {
		var err error
		draft, err = d.e.store.GetDraft(ctx, tx, draftID)
		return err
	})
	switch {
	case errors.Is(err, store.ErrNotFound):
		return 0, fmt.Errorf("%w: draft %s", ErrNotFound, id)
	case err != nil:
		return 0, fmt.Errorf("flowkit: publish draft %s: %w", id, err)
	}
	v, verrs := d.e.reg.validateDefinition(draft.Body)
	if len(verrs) > 0 {
		return 0, verrs
	}
	checksum, err := definitionChecksum(draft.Body)
	if err != nil {
		return 0, fmt.Errorf("flowkit: publish draft %s: %w", id, err)
	}

	var version int
	err = d.e.inTx(ctx, func(tx store.Tx) error {
		now := d.e.cfg.Clock.Now()
		row := routeColumns(draft.Name, v)
		row.Enabled, row.CreatedAt, row.UpdatedAt = true, now, now
		if _, err := d.e.store.InsertDefinitionIfAbsent(ctx, tx, row); err != nil {
			return err
		}
		current, err := d.e.store.LockDefinition(ctx, tx, draft.Name)
		if err != nil {
			return err
		}
		version = 1
		if current.CurrentVersion != nil {
			version = *current.CurrentVersion + 1
		}
		err = d.e.store.InsertDefinitionVersion(ctx, tx, store.DefinitionVersionRow{
			Name:             draft.Name,
			Version:          version,
			Body:             draft.Body,
			MetamodelVersion: v.def.MetamodelVersion,
			Checksum:         checksum,
			PublishedBy:      optional(opts.Actor),
			Note:             optional(opts.Note),
			PublishedAt:      now,
		})
		if err != nil {
			return err
		}
		refs := make([]store.ComponentRef, len(v.refs))
		for i, r := range v.refs {
			refs[i] = store.ComponentRef{Kind: r.Kind, Ref: r.Ref}
		}
		if err := d.e.store.InsertComponentRefs(ctx, tx, draft.Name, version, refs); err != nil {
			return err
		}
		row.CurrentVersion, row.UpdatedAt = &version, now
		return d.e.store.UpdateDefinitionPublished(ctx, tx, row)
	})
	if err != nil {
		return 0, fmt.Errorf("flowkit: publish draft %s: %w", id, err)
	}
	return Version(version), nil
}

// routeColumns are the definition columns routing reads instead of the
// body.
func routeColumns(name string, v *validatedDefinition) store.DefinitionRow {
	c := v.def.Concurrency
	row := store.DefinitionRow{Name: name, ConcurrencyPolicy: c.Policy}
	row.TriggerEventType = &v.def.Trigger.Event
	if c.SerialKey != "" {
		row.SerialKeyCEL = &c.SerialKey
	}
	if c.DedupWindow > 0 {
		seconds := int(c.DedupWindow / time.Second)
		row.DedupWindowSeconds = &seconds
	}
	return row
}

// Enable lets the definition start runs again and, in the same
// transaction, schedules every run of it in state running to continue.
// Waiting runs need nothing: their waits are claimed while disabled too.
// Enabling an enabled definition schedules its running runs again; the
// extra jobs find nothing to do.
//
// Enable, Disable, Get and PinnedRuns return ErrNotFound for a name no
// definition can have, as SaveDraft would refuse it.
func (d *Definitions) Enable(ctx context.Context, name string) error {
	if err := checkLookupName(name); err != nil {
		return err
	}
	err := d.e.inTx(ctx, func(tx store.Tx) error {
		if err := d.e.store.SetDefinitionEnabled(ctx, tx, name, true, d.e.cfg.Clock.Now()); err != nil {
			return err
		}
		running, err := d.e.store.ListRunningRunIDs(ctx, tx, name)
		if err != nil {
			return err
		}
		return d.e.jobs.EnqueuePumpMany(ctx, tx, running)
	})
	return d.lifecycleErr("enable", name, err)
}

// Disable stops the definition from starting runs, and its running runs
// from taking further steps until Enable.
func (d *Definitions) Disable(ctx context.Context, name string) error {
	if err := checkLookupName(name); err != nil {
		return err
	}
	err := d.e.inTx(ctx, func(tx store.Tx) error {
		return d.e.store.SetDefinitionEnabled(ctx, tx, name, false, d.e.cfg.Clock.Now())
	})
	return d.lifecycleErr("disable", name, err)
}

func (d *Definitions) lifecycleErr(op, name string, err error) error {
	switch {
	case err == nil:
		return nil
	case errors.Is(err, store.ErrNotFound):
		return fmt.Errorf("%w: definition %q", ErrNotFound, name)
	}
	return fmt.Errorf("flowkit: %s definition %q: %w", op, name, err)
}

// Get returns a published version, or ErrNotFound.
func (d *Definitions) Get(ctx context.Context, name string, version int) (DefinitionVersion, error) {
	if err := checkLookupName(name); err != nil {
		return DefinitionVersion{}, err
	}
	var row store.DefinitionVersionRow
	err := d.e.inTx(ctx, func(tx store.Tx) error {
		var err error
		row, err = d.e.store.GetDefinitionVersion(ctx, tx, name, version)
		return err
	})
	switch {
	case errors.Is(err, store.ErrNotFound):
		return DefinitionVersion{}, fmt.Errorf("%w: definition %q version %d", ErrNotFound, name, version)
	case err != nil:
		return DefinitionVersion{}, fmt.Errorf("flowkit: get definition %q version %d: %w", name, version, err)
	}
	return DefinitionVersion{
		Name:             row.Name,
		Version:          row.Version,
		Body:             row.Body,
		MetamodelVersion: row.MetamodelVersion,
		Checksum:         row.Checksum,
		PublishedBy:      deref(row.PublishedBy),
		Note:             deref(row.Note),
		PublishedAt:      row.PublishedAt,
	}, nil
}

// Refs returns the published definition versions that use ref, ordered by
// name and version.
func (d *Definitions) Refs(ctx context.Context, ref ComponentRef) ([]DefinitionRef, error) {
	switch ref.Kind {
	case ComponentEvent, ComponentAction, ComponentFact:
	default:
		return nil, fmt.Errorf("flowkit: refs: unknown component kind %q", ref.Kind)
	}
	var rows []store.DefinitionRef
	err := d.e.inTx(ctx, func(tx store.Tx) error {
		var err error
		rows, err = d.e.store.ListComponentUsers(ctx, tx, store.ComponentRef{Kind: ref.Kind, Ref: ref.Ref})
		return err
	})
	if err != nil {
		return nil, fmt.Errorf("flowkit: refs of %s %q: %w", ref.Kind, ref.Ref, err)
	}
	out := make([]DefinitionRef, len(rows))
	for i, r := range rows {
		out[i] = DefinitionRef{Name: r.Name, Version: r.Version}
	}
	return out, nil
}

// PinnedRuns counts the definition's runs that have not finished, by the
// version they run. A version absent from the map has none.
func (d *Definitions) PinnedRuns(ctx context.Context, name string) (map[int]int, error) {
	if err := checkLookupName(name); err != nil {
		return nil, err
	}
	var out map[int]int
	err := d.e.inTx(ctx, func(tx store.Tx) error {
		var err error
		out, err = d.e.store.CountPinnedRuns(ctx, tx, name)
		return err
	})
	if err != nil {
		return nil, fmt.Errorf("flowkit: pinned runs of %q: %w", name, err)
	}
	return out, nil
}

// inTx runs fn in a store transaction, committing when fn succeeds.
func (e *Engine) inTx(ctx context.Context, fn func(store.Tx) error) (err error) {
	tx, err := e.store.Begin(ctx)
	if err != nil {
		return err
	}
	defer func() {
		if err != nil {
			// The rollback error adds nothing to err.
			_ = tx.Rollback(context.WithoutCancel(ctx))
		}
	}()
	if err := fn(tx); err != nil {
		return err
	}
	return tx.Commit(ctx)
}

func checkDefinitionName(name string) error {
	switch {
	case name == "":
		return errors.New("flowkit: definition name is required")
	case len(name) > maxDefinitionNameBytes:
		return fmt.Errorf("flowkit: definition name is %d bytes, more than %d", len(name), maxDefinitionNameBytes)
	}
	if problem := textProblem(name); problem != "" {
		return fmt.Errorf("flowkit: definition name %s", problem)
	}
	return nil
}

// checkLookupName returns ErrNotFound for a name SaveDraft refuses, which
// no definition can have and Postgres may not take as text.
func checkLookupName(name string) error {
	if checkDefinitionName(name) != nil {
		return fmt.Errorf("%w: no definition can be named %q", ErrNotFound, name)
	}
	return nil
}

// definitionChecksum hashes the canonical form of body: object keys
// sorted, no insignificant space, integers in plain base 10.
func definitionChecksum(body json.RawMessage) (string, error) {
	doc, err := schema.Decode(body)
	if err != nil {
		return "", fmt.Errorf("checksum: %w", err)
	}
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(canonicalJSON(doc)); err != nil {
		return "", fmt.Errorf("checksum: %w", err)
	}
	sum := sha256.Sum256(bytes.TrimSuffix(buf.Bytes(), []byte("\n")))
	return hex.EncodeToString(sum[:]), nil
}

// canonicalJSON rewrites the integers of a decoded document in plain base
// 10. encoding/json sorts object keys when it marshals a map. A body read
// back from jsonb spells no exponent; one with an exponent past
// maxNumberExponent, which validation rejects, keeps its spelling rather
// than cost a huge expansion.
func canonicalJSON(v any) any {
	switch x := v.(type) {
	case map[string]any:
		for k, e := range x {
			x[k] = canonicalJSON(e)
		}
	case []any:
		for i, e := range x {
			x[i] = canonicalJSON(e)
		}
	case json.Number:
		s := x.String()
		if i := strings.IndexAny(s, "eE"); i >= 0 {
			exp, err := strconv.Atoi(s[i+1:])
			if err != nil || exp > maxNumberExponent || exp < -maxNumberExponent {
				return x
			}
		}
		r, ok := new(big.Rat).SetString(s)
		if !ok || !r.IsInt() {
			return x
		}
		return json.Number(r.Num().String())
	}
	return v
}

func optional(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}

func deref(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}
